  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  code                         varchar(64) NOT NULL,
  name                         varchar(160) NOT NULL,
  owning_service               varchar(64) NOT NULL,
  http_method                  varchar(40) NOT NULL DEFAULT 'POST' CHECK (http_method IN ('POST', 'PUT', 'PATCH', 'GET')),
  http_path                    varchar(500) NOT NULL,
  cron_expression              varchar(64) NOT NULL,
  time_zone                    varchar(64) NOT NULL DEFAULT 'UTC',
  business_days_only           boolean NOT NULL DEFAULT false,
  holiday_calendar_id          uuid,
  status                       varchar(40) NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'PAUSED', 'DISABLED')),
  parameters                   jsonb,
  last_run_at                  timestamptz,
  last_run_status              varchar(40) CHECK (last_run_status IN ('QUEUED', 'RUNNING', 'SUCCEEDED', 'FAILED', 'CANCELLED', 'PARTIALLY_SUCCEEDED')),
  next_run_at                  timestamptz,
  misfire_policy               varchar(32) NOT NULL DEFAULT 'RUN_ONCE',
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500),
  CONSTRAINT uq_job_schedule_code UNIQUE (tenant_id, code)
);
COMMENT ON TABLE job_schedule IS 'Cron schedule for non-EOD batch jobs (sweeps, report generation, file pulls, reindexing)';
COMMENT ON COLUMN job_schedule.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN job_schedule.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN job_schedule.created_at IS 'Creation time';
COMMENT ON COLUMN job_schedule.created_by IS 'Principal that created the row';
COMMENT ON COLUMN job_schedule.updated_at IS 'Last update time';
COMMENT ON COLUMN job_schedule.updated_by IS 'Principal that last updated the row';
COMMENT ON COLUMN job_schedule.row_version IS 'Optimistic lock version; send as If-Match';
COMMENT ON COLUMN job_schedule.code IS 'Schedule code';
COMMENT ON COLUMN job_schedule.name IS 'Display name';
COMMENT ON COLUMN job_schedule.owning_service IS 'Service that runs the job';
COMMENT ON COLUMN job_schedule.http_method IS 'HTTP method of the job endpoint';
COMMENT ON COLUMN job_schedule.http_path IS 'Path on the owning service, called with X-Tenant-Id and Idempotency-Key jsr:<schedule id>:<run key>';
COMMENT ON COLUMN job_schedule.cron_expression IS 'Cron expression';
COMMENT ON COLUMN job_schedule.time_zone IS 'IANA time zone';
COMMENT ON COLUMN job_schedule.business_days_only IS 'Skip non-business days';
COMMENT ON COLUMN job_schedule.holiday_calendar_id IS 'Calendar for business-day checks';
COMMENT ON COLUMN job_schedule.status IS 'Status';
COMMENT ON COLUMN job_schedule.parameters IS 'Parameters passed to the job';
COMMENT ON COLUMN job_schedule.last_run_at IS 'Last execution start';
COMMENT ON COLUMN job_schedule.last_run_status IS 'Last execution status';
COMMENT ON COLUMN job_schedule.next_run_at IS 'Next planned execution';
COMMENT ON COLUMN job_schedule.misfire_policy IS 'RUN_ONCE, SKIP or RUN_ALL after downtime';
COMMENT ON COLUMN job_schedule.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN job_schedule.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN job_schedule.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN job_schedule.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN job_schedule.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_job_schedule_tenant ON job_schedule (tenant_id, created_at);
CREATE INDEX ix_job_schedule_holiday_calendar_id ON job_schedule (holiday_calendar_id);
ALTER TABLE job_schedule ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON job_schedule USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_job_schedule_touch BEFORE UPDATE ON job_schedule FOR EACH ROW EXECUTE FUNCTION touch_row();

-- job_schedule_run: One execution of a scheduled batch job. Append-only.
CREATE TABLE job_schedule_run (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  job_schedule_id              uuid NOT NULL REFERENCES job_schedule(id),
  scheduled_for                timestamptz NOT NULL,
  started_at                   timestamptz,
  finished_at                  timestamptz,
  status                       varchar(40) NOT NULL CHECK (status IN ('QUEUED', 'RUNNING', 'SUCCEEDED', 'FAILED', 'CANCELLED', 'PARTIALLY_SUCCEEDED')),
  records_processed            bigint,
  error                        text,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500)
);
COMMENT ON TABLE job_schedule_run IS 'One execution of a scheduled batch job. Append-only.';
COMMENT ON COLUMN job_schedule_run.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN job_schedule_run.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN job_schedule_run.created_at IS 'Creation time';
COMMENT ON COLUMN job_schedule_run.created_by IS 'Principal that created the row';
COMMENT ON COLUMN job_schedule_run.job_schedule_id IS 'Schedule';
COMMENT ON COLUMN job_schedule_run.scheduled_for IS 'Planned time';
COMMENT ON COLUMN job_schedule_run.started_at IS 'Start time';
COMMENT ON COLUMN job_schedule_run.finished_at IS 'End time';
COMMENT ON COLUMN job_schedule_run.status IS 'Outcome';
COMMENT ON COLUMN job_schedule_run.records_processed IS 'Records processed';
COMMENT ON COLUMN job_schedule_run.error IS 'Error details';
COMMENT ON COLUMN job_schedule_run.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN job_schedule_run.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN job_schedule_run.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN job_schedule_run.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN job_schedule_run.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_job_schedule_run_tenant ON job_schedule_run (tenant_id, created_at);
CREATE INDEX ix_job_schedule_run_job_schedule_id ON job_schedule_run (job_schedule_id);
ALTER TABLE job_schedule_run ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON job_schedule_run USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_job_schedule_run_append_only BEFORE UPDATE OR DELETE ON job_schedule_run FOR EACH ROW EXECUTE FUNCTION forbid_mutation();

-- batch_job_lock: Distributed lock preventing concurrent execution of the same batch job or partition
CREATE TABLE batch_job_lock (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  lock_key                     varchar(160) NOT NULL,
  holder                       varchar(128) NOT NULL,
  acquired_at                  timestamptz NOT NULL DEFAULT now(),
  expires_at                   timestamptz NOT NULL,
  fencing_token                bigint NOT NULL DEFAULT 0,
  force_released_at            timestamptz,
  force_released_by            varchar(64),
  force_release_reason         varchar(500),
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500),
  CONSTRAINT uq_batch_job_lock_lock_key UNIQUE (tenant_id, lock_key)
);
COMMENT ON TABLE batch_job_lock IS 'Distributed lock preventing concurrent execution of the same batch job or partition';
COMMENT ON COLUMN batch_job_lock.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN batch_job_lock.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN batch_job_lock.created_at IS 'Creation time';
COMMENT ON COLUMN batch_job_lock.created_by IS 'Principal that created the row';
COMMENT ON COLUMN batch_job_lock.updated_at IS 'Last update time';
COMMENT ON COLUMN batch_job_lock.updated_by IS 'Principal that last updated the row';
COMMENT ON COLUMN batch_job_lock.row_version IS 'Optimistic lock version; send as If-Match';
COMMENT ON COLUMN batch_job_lock.lock_key IS 'Job / partition key';
COMMENT ON COLUMN batch_job_lock.holder IS 'Instance id holding the lock';
COMMENT ON COLUMN batch_job_lock.acquired_at IS 'Acquired';
COMMENT ON COLUMN batch_job_lock.expires_at IS 'Lease expiry';
COMMENT ON COLUMN batch_job_lock.fencing_token IS 'Monotonic token to reject stale holders';
COMMENT ON COLUMN batch_job_lock.force_released_at IS 'When an operator last force-released the lock';
COMMENT ON COLUMN batch_job_lock.force_released_by IS 'Operator who force-released the lock';
COMMENT ON COLUMN batch_job_lock.force_release_reason IS 'Why the lock was force-released';
COMMENT ON COLUMN batch_job_lock.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN batch_job_lock.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN batch_job_lock.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN batch_job_lock.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN batch_job_lock.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_batch_job_lock_tenant ON batch_job_lock (tenant_id, created_at);
ALTER TABLE batch_job_lock ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON batch_job_lock USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_batch_job_lock_touch BEFORE UPDATE ON batch_job_lock FOR EACH ROW EXECUTE FUNCTION touch_row();

-- Transactional outbox: events are written here in the same transaction as the
-- state change and relayed to Kafka by the outbox relay (Debezium).
CREATE TABLE outbox (
  id              uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id       uuid NOT NULL,
  aggregate_type  varchar(64) NOT NULL,
  aggregate_id    uuid NOT NULL,
  event_type      varchar(128) NOT NULL,
  payload         jsonb NOT NULL,
  headers         jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_outbox_created ON outbox (created_at);

-- Idempotency keys for POST requests (24h retention).
CREATE TABLE idempotency_key (
  tenant_id       uuid NOT NULL,
  key             varchar(128) NOT NULL,
  request_hash    varchar(64) NOT NULL,
  response_status integer,
  response_body   jsonb,
  created_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, key)
);

-- Runtime access for the non-superuser application role (RLS does not apply to superusers).
DO $$
BEGIN
  IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'meridian_app') THEN
    GRANT USAGE ON SCHEMA business_day TO meridian_app;
    GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA business_day TO meridian_app;
    ALTER DEFAULT PRIVILEGES IN SCHEMA business_day GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO meridian_app;
  END IF;
END $$;
